import { beforeEach, describe, expect, it, vi } from "vitest";
import { randomUUID } from "node:crypto";
const mocks = vi.hoisted(() => ({ auth: vi.fn(), dismiss: vi.fn() }));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/account-notices", () => ({
  dismissAccountNotice: mocks.dismiss,
}));
import { POST } from "@/app/api/account/notices/route";
beforeEach(() => vi.resetAllMocks());
const request = (body: unknown) =>
  new Request("http://localhost/api/account/notices", {
    method: "POST",
    body: JSON.stringify(body),
  });
describe("authenticated notice dismissal", () => {
  it("requires a session and never accepts a caller-supplied owner", async () => {
    mocks.auth.mockResolvedValue(null);
    expect((await POST(request({ noticeId: randomUUID() }))).status).toBe(401);
    mocks.auth.mockResolvedValue({ user: { id: "session-owner" } });
    expect(
      (await POST(request({ noticeId: randomUUID(), userId: "other" }))).status,
    ).toBe(400);
    expect(mocks.dismiss).not.toHaveBeenCalled();
  });
  it("scopes dismissal to the authenticated owner and prevents caching", async () => {
    const noticeId = randomUUID();
    mocks.auth.mockResolvedValue({ user: { id: "session-owner" } });
    const response = await POST(request({ noticeId }));
    expect(response.status).toBe(200);
    expect(response.headers.get("Cache-Control")).toBe("private, no-store");
    expect(mocks.dismiss).toHaveBeenCalledWith("session-owner", noticeId);
  });
});
